import { readFile } from 'node:fs/promises'
import {
    FluentXmlFluentTest,
    XmlFluentXmlTest,
    xml,
    createProject,
    runTestOnFunction,
    validateDiagnostic,
} from '../../test-utils'
import { Project } from '../../../src'
import { ts } from '@servicenow/sdk-build-core'

const SCOPE = 'x_ccstest'
interface TestCase {
    tsFile: string
    xmlFile: string
}

const testCasesFluentToXML: TestCase[] = [
    {
        tsFile: '../xml/catalog-client-script/create/catalogclientscript.now.ts',
        xmlFile: '../xml/catalog-client-script/create/catalogclientscript-create-result.xml',
    },
    {
        tsFile: '../xml/catalog-client-script/create/catalogclientscript0.now.ts',
        xmlFile: '../xml/catalog-client-script/create/catalogclientscript0-create-result.xml',
    },
    {
        tsFile: '../xml/catalog-client-script/create/catalogclientscript1.now.ts',
        xmlFile: '../xml/catalog-client-script/create/catalogclientscript1-create-result.xml',
    },
    {
        tsFile: '../xml/catalog-client-script/create/catalogclientscript2.now.ts',
        xmlFile: '../xml/catalog-client-script/create/catalogclientscript2-create-result.xml',
    },
    {
        tsFile: '../xml/catalog-client-script/create/catalogclientscript3.now.ts',
        xmlFile: '../xml/catalog-client-script/create/catalogclientscript3-create-result.xml',
    },
]

const testCasesXMLtoFluent: TestCase[] = [
    {
        xmlFile: '../xml/catalog-client-script/update/catalogclientscript.xml',
        tsFile: '../xml/catalog-client-script/update/catalogclientscript-update.now.ts',
    },
    {
        xmlFile: '../xml/catalog-client-script/update/catalogclientscript0.xml',
        tsFile: '../xml/catalog-client-script/update/catalogclientscript0-update.now.ts',
    },
    {
        xmlFile: '../xml/catalog-client-script/update/catalogclientscript1.xml',
        tsFile: '../xml/catalog-client-script/update/catalogclientscript1-update.now.ts',
    },
    {
        xmlFile: '../xml/catalog-client-script/update/catalogclientscript2.xml',
        tsFile: '../xml/catalog-client-script/update/catalogclientscript2-update.now.ts',
    },
    {
        xmlFile: '../xml/catalog-client-script/update/catalogclientscript3.xml',
        tsFile: '../xml/catalog-client-script/update/catalogclientscript3-update.now.ts',
    },
]
describe('CatalogClientScript plugin test suite', () => {
    describe('Validations and diagnostics', () => {
        test('validates variable belongs to catalog item', async () => {
            const project = createProject({ config: { scope: SCOPE } })

            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports
                const testCatalogItem = CatalogItem({
                    $id: Now.ID['test_catalog_item'],
                    name: 'Test Catalog Item',
                    variables: {
                        //@ts-expect-error avoid imports
                        itemVar: SingleLineTextVariable({
                            question: 'Item Variable',
                        }),
                    },
                })

                //@ts-expect-error avoid imports
                const otherVariableSet = VariableSet({
                    $id: Now.ID['other_variable_set'],
                    title: 'Other Variable Set',
                    variables: {
                        //@ts-expect-error avoid imports
                        setVar: SingleLineTextVariable({
                            question: 'Set Variable',
                        }),
                    },
                })

                //@ts-expect-error avoid imports
                CatalogClientScript({
                    $id: Now.ID['invalid_client_script'],
                    catalogItem: testCatalogItem,
                    appliesTo: 'item',
                    name: 'Invalid Client Script',
                    type: 'onChange',
                    variableName: otherVariableSet.variables.setVar,
                    script: 'console.log("test")',
                })
            })

            validateDiagnostic(output, ts.SyntaxKind.Identifier, 'Variable is not in the catalog item')
        })

        test('emits diagnostic when both catalogItem and variableSet are specified', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports
                CatalogClientScript({
                    $id: Now.ID['both_item_and_set'],
                    name: 'Both Item and Set',
                    type: 'onLoad',
                    script: 'console.log("test")',
                    catalogItem: 'some-catalog-item',
                    variableSet: 'some-variable-set',
                    appliesTo: 'item',
                })
            })
            validateDiagnostic(
                output,
                ts.SyntaxKind.ObjectLiteralExpression,
                "CatalogClientScript: 'catalogItem' and 'variableSet' are mutually exclusive. Specify only one. When appliesTo is 'set', use variableSet; when 'item', use catalogItem."
            )
        })

        test('emits diagnostic when catalogItem specified with appliesTo set', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports
                CatalogClientScript({
                    $id: Now.ID['item_with_set_applies'],
                    name: 'Item with Set AppliesTo',
                    type: 'onLoad',
                    script: 'console.log("test")',
                    catalogItem: 'some-catalog-item',
                    appliesTo: 'set',
                })
            })
            validateDiagnostic(
                output,
                ts.SyntaxKind.StringLiteral,
                "CatalogClientScript: 'catalogItem' should not be specified when appliesTo is 'set'. Use 'variableSet' instead."
            )
        })

        test('emits diagnostic when variableSet specified with appliesTo item', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports
                CatalogClientScript({
                    $id: Now.ID['set_with_item_applies'],
                    name: 'Set with Item AppliesTo',
                    type: 'onLoad',
                    script: 'console.log("test")',
                    variableSet: 'some-variable-set',
                    appliesTo: 'item',
                })
            })
            validateDiagnostic(
                output,
                ts.SyntaxKind.StringLiteral,
                "CatalogClientScript: 'variableSet' should not be specified when appliesTo is 'item'. Use 'catalogItem' instead."
            )
        })

        test('no diagnostic when only catalogItem is specified with appliesTo item', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports
                CatalogClientScript({
                    $id: Now.ID['valid_item_only'],
                    name: 'Valid Item Only',
                    type: 'onLoad',
                    script: 'console.log("test")',
                    catalogItem: 'some-catalog-item',
                    appliesTo: 'item',
                })
            })
            expect(output.filter((d) => d.message.includes('mutually exclusive'))).toHaveLength(0)
        })

        test('validates variable belongs to variable set', async () => {
            const project = createProject({ config: { scope: SCOPE } })

            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports
                const testVariableSet = VariableSet({
                    $id: Now.ID['test_variable_set'],
                    title: 'Test Variable Set',
                    variables: {
                        //@ts-expect-error avoid imports
                        setVar: SingleLineTextVariable({
                            question: 'Set Variable',
                        }),
                    },
                })

                //@ts-expect-error avoid imports
                const otherVariableSet = VariableSet({
                    $id: Now.ID['other_variable_set'],
                    title: 'Other Variable Set',
                    variables: {
                        //@ts-expect-error avoid imports
                        otherVar: SingleLineTextVariable({
                            question: 'Other Variable',
                        }),
                    },
                })

                //@ts-expect-error avoid imports
                CatalogClientScript({
                    $id: Now.ID['invalid_set_client_script'],
                    variableSet: testVariableSet,
                    appliesTo: 'set',
                    name: 'Invalid Set Client Script',
                    type: 'onChange',
                    variableName: otherVariableSet.variables.otherVar,
                    script: 'console.log("test")',
                })
            })

            validateDiagnostic(output, ts.SyntaxKind.Identifier, 'Variable is not in the variable set')
        })
    })

    describe('Fluent to XML', () => {
        test.each(testCasesFluentToXML)('creates XML from Fluent API', async ({ tsFile, xmlFile }) => {
            const project = createProject({ config: { scope: SCOPE } })
            project.addFile(`${__dirname}/../xml/catalog-client-script/create/script.now.ts`)
            const file = project.addFile({
                path: `${__dirname}/../xml/catalog-client-script/create/catalogclientscript.now.ts`,
                content: await readFile(`${__dirname}/${tsFile}`, 'utf8'),
            })
            project.registerExplicitId('catalog_script_client', 'sc_ccs_id', 'sc_ccs_id')
            project.registerExplicitId('catalog_script_client', 'test-catalog-item', 'test-catalog-item')
            project.registerExplicitId('catalog_script_client', 'variable-name', 'variable-name')
            const output = await file.getOutput()
            expect(output).toHaveLength(1)

            const expected = await readFile(`${__dirname}/${xmlFile}`, 'utf8')
            expect(output[0].content.trim()).toEqual(expected.trim())
        })
    })
    describe('XML to Fluent', () => {
        test.each(testCasesXMLtoFluent)('creates Fluent from XML record', async ({ xmlFile, tsFile }) => {
            const project = createProject({ config: { scope: SCOPE } })
            const result = await project.transform(`${__dirname}/${xmlFile}`)
            const content = result.changedFiles[0]?.getContent()
            const expected = await readFile(`${__dirname}/${tsFile}`, 'utf8')
            expect(content.trim()).toEqual(expected.trim())
        })
    })
    describe('Fluent => XML => Fluent', () => {
        test('file can round-trip correctly', async () => {
            const project = createProject({ config: { scope: SCOPE } })
            const roundTripTest = new FluentXmlFluentTest(project)
            const catalogClientScriptId = roundTripTest.addId('catalog_script_client', 'sc_ccs_id')
            roundTripTest.addExpectedXmlFileNames(`catalog_script_client_${catalogClientScriptId}.xml`)
            roundTripTest.addFluentFragment(
                `
import { CatalogClientScript } from '@servicenow/sdk/core'

CatalogClientScript({
    $id: Now.ID['sc_ccs_id'],
    name: 'catalog client script test1',
    type: 'onLoad',
    script: 'function onLoad(){ g_form.addInfoMessage("hello") }',
    catalogItem: 'test-catalog-item',
    uiType: 'all'
})
`
            )

            await roundTripTest.verify()
        })

        test('can transform backtick characters in code', async () => {
            const project = new Project()
            const {
                changedFiles: [file],
            } = await project.transform({
                path: 'client_script.xml',
                content: `
<?xml version="1.0"?>
<record_update>
  <catalog_script_client action="INSERT_OR_UPDATE">
    <sys_id>7fb2eb8fd63b440aa52f0493c4fccb5a</sys_id>
    <sys_scope display_value="x_ccstest">aaaa1111bbbb2222cccc3333dddd4444</sys_scope>
    <sys_update_name>catalog_script_client_7fb2eb8fd63b440aa52f0493c4fccb5a</sys_update_name>
    <active>true</active>
    <applies_catalog>true</applies_catalog>
    <applies_req_item>false</applies_req_item>
    <applies_sc_task>false</applies_sc_task>
    <applies_target_record>false</applies_target_record>
    <applies_to>item</applies_to>
    <cat_item>d845c39f20f448bd8e8adfc48cfab2ea</cat_item>
    <cat_variable>IO:525bc6ba7a9746ac905ffd4a4015a12b</cat_variable>
    <global>true</global>
    <name>catalog client script test2</name>
    <published_ref/>
    <script><![CDATA[function onLoad() {
    g_form.addInfoMessage(\`cool backticks\`)
}]]></script>
    <type>onChange</type>
    <ui_type>0</ui_type>
    <va_supported>false</va_supported>
    <variable_set/>
  </catalog_script_client>
</record_update>
                    `,
            })

            expect(file.getContent()).toContain(
                `script: Now.include('./catalog_script_client_7fb2eb8fd63b440aa52f0493c4fccb5a-script.js')`
            )
        })
    })
    describe('XML => Fluent => XML', () => {
        test('files can round-trip correctly', async () => {
            const project = createProject({
                rootDir: __dirname,
                config: { scope: SCOPE },
            })
            const originalFiles = [
                {
                    path: 'catalog_script_client_7fb2eb8fd63b440aa52f0493c4fccb5a.xml',
                    content: xml`<?xml version="1.0"?>
<record_update>
  <catalog_script_client action="INSERT_OR_UPDATE">
    <sys_id>7fb2eb8fd63b440aa52f0493c4fccb5a</sys_id>
    <sys_scope display_value="x_ccstest">11111111111111111111111111111111</sys_scope>
    <sys_update_name>catalog_script_client_sc_ccs_id</sys_update_name>
    <active>true</active>
    <applies_catalog>true</applies_catalog>
    <applies_req_item>false</applies_req_item>
    <applies_sc_task>false</applies_sc_task>
    <applies_target_record>false</applies_target_record>
    <applies_to>item</applies_to>
    <cat_item>d845c39f20f448bd8e8adfc48cfab2ea</cat_item>
    <cat_variable/>
    <global>true</global>
    <isolate_script>true</isolate_script>
    <name>catalog client script test1</name>
    <published_ref/>
    <script><![CDATA[function onLoad(){ g_form.addInfoMessage("hello") }]]></script>
    <type>onLoad</type>
    <ui_type>10</ui_type>
    <va_supported>false</va_supported>
    <variable_set/>
  </catalog_script_client>
</record_update>
`,
                },
            ]
            const roundTripTest = new XmlFluentXmlTest(project, __dirname, originalFiles)
            await roundTripTest.verify()
        })
    })
})
